// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

uint256 constant VALUE_CAP = 1000000000000000000000000000000;

contract InvMutTest is Test {
    SimpleWallet c;
    Recorder rec;
    function setUp() public { c = new SimpleWallet(); rec = new Recorder(); }

    function testFuzz_property(uint256 amount) public {
        vm.assume(amount <= VALUE_CAP);
        amount = bound(amount, 0, type(uint128).max);
        // fund c through its receive() from an external funder
        vm.deal(address(this), amount);
        (bool okFund, ) = address(c).call{value: amount}("");
        assertTrue(okFund);
        assertEq(address(c).balance, amount);
        // owner (deployer = this test contract) forwards amount to the recorder
        vm.prank(address(this));
        c.sendMoney(address(rec), amount);
        // RULE: the counterparty receives exactly the amount forwarded
        assertEq(rec.received(), amount);
        assertEq(address(c).balance, 0);
    }
}

contract Recorder {
    uint public received;
    fallback() external payable { received += msg.value; }
    receive() external payable { received += msg.value; }
}
